const ret0 = Date.now();
const returnLadder = [];
let originLanded = false;
let lastLadderSig = '';
while (Date.now() - ret0 < returnBudgetMs) {
  const rSt = await readState(page);
  const rCg = await cgSnap(page);
  const ms = rSt?.milestones ?? [];
  const sig = `${rSt?.beat}|${rSt?.objectiveId}|${(rCg?.anchors ?? []).join(',')}`;
