    const legA = await walkTowards(page, [-34, 51.05, 12], { budgetMs: Math.round(walkBudgetMs / 2), arriveUnits: 1.4, say });
    for (const j of legA.journey) emit({ phase: 'walk-to-route-plane', ...j });
