print('samples',len(xs))
# find local minima/maxima runs
prev=None; turns=[]
for i in range(1,len(xs)-1):
    a,b,c=xs[i-1][1],xs[i][1],xs[i+1][1]
    if b<=a and b<=c and (a-b)>20: turns.append(('MIN',xs[i][0],b))
